package com.idlebox;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.Color;

@ConfigGroup(IdleBoxConfig.GROUP)
public interface IdleBoxConfig extends Config
{
	String GROUP = "idlebox";

	@ConfigItem(
		keyName = "idleSeconds",
		name = "Idle seconds",
		description = "Seconds without animation, interaction, movement or XP before showing the indicator",
		position = 1
	)
	default int idleSeconds()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "showOverlaySquare",
		name = "Show square",
		description = "Shows a colored square on screen while idle",
		position = 2
	)
	default boolean showOverlaySquare()
	{
		return true;
	}

	@ConfigItem(
		keyName = "squareColor",
		name = "Square color",
		description = "Color of the square shown while idle",
		position = 3
	)
	default Color squareColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "squareSize",
		name = "Square size",
		description = "Side of the square in pixels",
		position = 4
	)
	default int squareSize()
	{
		return 24;
	}

	@ConfigItem(
		keyName = "showInfoBox",
		name = "Show InfoBox",
		description = "Shows an InfoBox (icon + text) while idle",
		position = 5
	)
	default boolean showInfoBox()
	{
		return true;
	}
}

package com.idlebox;

import net.runelite.client.ui.overlay.infobox.InfoBox;

import java.awt.Color;
import java.awt.image.BufferedImage;

public class IdleBoxInfoBox extends InfoBox
{
	IdleBoxInfoBox(BufferedImage image, IdleBoxPlugin plugin)
	{
		super(image, plugin);
	}

	@Override
	public String getText()
	{
		return "IDLE";
	}

	@Override
	public Color getTextColor()
	{
		return Color.RED;
	}

	@Override
	public String getTooltip()
	{
		return "You've been idle without activity";
	}
}

package com.idlebox;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;

public class IdleBoxOverlay extends Overlay
{
	private final IdleBoxPlugin plugin;
	private final IdleBoxConfig config;

	@Inject
	private IdleBoxOverlay(IdleBoxPlugin plugin, IdleBoxConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlaySquare() || !plugin.isIdle())
		{
			return null;
		}

		int size = config.squareSize();
		graphics.setColor(config.squareColor());
		graphics.fillRect(0, 0, size, size);

		return new Dimension(size, size);
	}
}

package com.idlebox;

import com.google.inject.Provides;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;

@PluginDescriptor(
	name = "Idle Box",
	description = "Shows an on-screen colored box and/or an InfoBox when the character has been idle for X seconds without animation, interaction, movement or XP",
	tags = {"idle", "afk", "indicator", "overlay", "status"}
)
public class IdleBoxPlugin extends Plugin
{
	// RuneLite runs at 0.6 seconds per game tick
	private static final double SECONDS_PER_TICK = 0.6;

	@Inject
	private Client client;

	@Inject
	private IdleBoxConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private IdleBoxOverlay overlay;

	@Inject
	private InfoBoxManager infoBoxManager;

	private boolean idle = false;
	private IdleBoxInfoBox infoBox;

	// Last game tick where ANY activity signal was detected
	private int lastActivityTick;

	private WorldPoint lastLocation;
	private final Map<Skill, Integer> lastKnownXp = new EnumMap<>(Skill.class);
	private boolean xpGainedThisTick;

	@Provides
	IdleBoxConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IdleBoxConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		lastActivityTick = client.getTickCount();
		lastLocation = null;
		lastKnownXp.clear();
		xpGainedThisTick = false;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		removeInfoBox();
		idle = false;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer previous = lastKnownXp.put(event.getSkill(), event.getXp());
		if (previous != null && event.getXp() > previous)
		{
			xpGainedThisTick = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int currentTick = client.getTickCount();
		boolean activeThisTick = false;

		Player local = client.getLocalPlayer();

		if (local != null)
		{
			boolean animating = local.getAnimation() != -1;
			boolean interacting = local.getInteracting() != null;

			WorldPoint currentLocation = local.getWorldLocation();
			boolean moved = lastLocation != null && !lastLocation.equals(currentLocation);
			lastLocation = currentLocation;

			activeThisTick = animating || interacting || moved || xpGainedThisTick;
		}

		xpGainedThisTick = false;

		if (activeThisTick)
		{
			lastActivityTick = currentTick;
		}

		int thresholdTicks = (int) Math.round(config.idleSeconds() / SECONDS_PER_TICK);
		boolean nowIdle = (currentTick - lastActivityTick) >= thresholdTicks;

		if (nowIdle == idle)
		{
			return;
		}

		idle = nowIdle;
		updateInfoBox();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!IdleBoxConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		updateInfoBox();
	}

	public boolean isIdle()
	{
		return idle;
	}

	private void updateInfoBox()
	{
		if (idle && config.showInfoBox())
		{
			addInfoBox();
		}
		else
		{
			removeInfoBox();
		}
	}

	private void addInfoBox()
	{
		if (infoBox != null)
		{
			return;
		}

		infoBox = new IdleBoxInfoBox(createIcon(), this);
		infoBoxManager.addInfoBox(infoBox);
	}

	private void removeInfoBox()
	{
		if (infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
		}
	}

	// Icon generated in code, no external resource dependency
	private BufferedImage createIcon()
	{
		BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.RED);
		g.fillOval(2, 2, 20, 20);
		g.setColor(Color.WHITE);
		g.drawOval(2, 2, 20, 20);
		g.dispose();
		return img;
	}
}

package com.idlebox;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class IdleBoxPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(IdleBoxPlugin.class);
		RuneLite.main(args);
	}
}
